ALTER TABLE accounts ADD COLUMN achievement_suffix VARCHAR(80) NULL;
CREATE TABLE card_packs (id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36) NOT NULL,name VARCHAR(80) NOT NULL,description VARCHAR(1000) NOT NULL,created_at VARCHAR(40) NOT NULL,CONSTRAINT fk_card_pack_user FOREIGN KEY(user_id) REFERENCES accounts(id) ON DELETE CASCADE);
CREATE TABLE cards (id VARCHAR(36) PRIMARY KEY,pack_id VARCHAR(36) NOT NULL,user_id VARCHAR(36) NOT NULL,title VARCHAR(120) NOT NULL,problem_key VARCHAR(40) NOT NULL,prompt VARCHAR(4000) NOT NULL,answer_hint VARCHAR(4000) NOT NULL,difficulty VARCHAR(20) NOT NULL,cf_url VARCHAR(500) NOT NULL,created_at VARCHAR(40) NOT NULL,CONSTRAINT fk_card_pack FOREIGN KEY(pack_id) REFERENCES card_packs(id) ON DELETE CASCADE,CONSTRAINT fk_card_user FOREIGN KEY(user_id) REFERENCES accounts(id) ON DELETE CASCADE);
CREATE TABLE card_draws (id VARCHAR(36) PRIMARY KEY,pack_id VARCHAR(36) NOT NULL,card_id VARCHAR(36) NOT NULL,user_id VARCHAR(36) NOT NULL,draw_day VARCHAR(10) NOT NULL,created_at VARCHAR(40) NOT NULL,UNIQUE KEY uq_card_draw(pack_id,user_id,draw_day),CONSTRAINT fk_draw_pack FOREIGN KEY(pack_id) REFERENCES card_packs(id) ON DELETE CASCADE,CONSTRAINT fk_draw_card FOREIGN KEY(card_id) REFERENCES cards(id) ON DELETE CASCADE);
CREATE TABLE card_completions (id VARCHAR(36) PRIMARY KEY,card_id VARCHAR(36) NOT NULL,user_id VARCHAR(36) NOT NULL,completed_at VARCHAR(40) NOT NULL,UNIQUE KEY uq_card_completion(card_id,user_id),CONSTRAINT fk_completion_card FOREIGN KEY(card_id) REFERENCES cards(id) ON DELETE CASCADE);
CREATE TABLE achievements (id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36) NOT NULL,code VARCHAR(80) NOT NULL,title VARCHAR(120) NOT NULL,description VARCHAR(500) NOT NULL,earned_at VARCHAR(40) NOT NULL,UNIQUE KEY uq_achievement(user_id,code),CONSTRAINT fk_achievement_user FOREIGN KEY(user_id) REFERENCES accounts(id) ON DELETE CASCADE);
CREATE TABLE card_credits (user_id VARCHAR(36) PRIMARY KEY,credits INT NOT NULL DEFAULT 0,CONSTRAINT fk_credit_user FOREIGN KEY(user_id) REFERENCES accounts(id) ON DELETE CASCADE);
